import{_ as r,l as S,o as a,c as o,v as s,p as l,x as i,d,i as c,S as n}from"./chunks/framework.InCnrqk-.js";const I=JSON.parse('{"title":"SCSI 栈","description":"","frontmatter":{"title":"SCSI 栈","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/scsi-stack.md","filePath":"cs/scsi-stack.md","lastUpdated":1789023840000}'),p={name:"cs/scsi-stack.md"};function C(h,e,A,m,u,B){const t=S("Mermaid");return a(),o("div",null,[e[1]||(e[1]=s('<h1 id="scsi-栈" tabindex="-1">SCSI 栈 <a class="header-anchor" href="#scsi-栈" aria-label="Permalink to &quot;SCSI 栈&quot;">​</a></h1><div class="epigraph"><p>Linux SCSI 把磁盘、磁带、光驱收成中层：命令描述块向下，块请求向上，主机适配器驱动只谈总线。</p><footer>—— 据 T10 SCSI 架构模型；Linux SCSI 中层文档；McKusick 对 CAM 的对照</footer></div><p><a href="/cs/nvme-driver">上一课</a>是寄存器队列。<a href="/cs/blk-schedulers">块层</a> 下面还可以是 SCSI：SATA 经 libata 翻译、SAS、USB mass storage、iSCSI。缺口是 <strong>SCSI 栈分层</strong>：sd 磁盘驱动、中层错误处理、主机（HBA）驱动，而不是再讲 NVMe 门铃。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>命令是 CDB（读、写、同步缓存、查询）。设备按 LUN 寻址。错误：sense 数据、重试、设备复位、主机复位——中层有 EH 线程。缺口：块请求如何变成 SCSI 命令；分区与 udev 仍看见 <code>/dev/sd*</code>；与 NVMe 并存时，通用块层是共同上接口。本课不把 iSCSI 会话的 TCP 细节写成网络课。</p><p><span class="marginnote">UASP、virtio-scsi、光纤通道都接同一中层。timeout 与 <code>scsi_eh</code> 是生产上的延迟来源。教学上记住「命令+感测」而不是厂商工具。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>sd</code> 把 bio 编成 READ/WRITE(10/16)，经中层排队到 HBA。完成回调把状态译成 blk 错误。对照 NVMe：多一次命令封装与错误模型。对照 <a href="/cs/device-nodes">设备节点</a>：主次号来自 SCSI 探测。扫描：<code>REPORT LUNS</code> 或总线扫描。</p>',8)),(a(),l(n,null,{default:i(()=>[c(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20BLK%5B%22%E5%9D%97%E5%B1%82%22%5D%20--%3E%20SD%5B%22sd%20%E7%A3%81%E7%9B%98%E7%B1%BB%E9%A9%B1%E5%8A%A8%22%5D%0A%20%20SD%20--%3E%20ML%5B%22SCSI%20%E4%B8%AD%E5%B1%82%22%5D%0A%20%20ML%20--%3E%20HBA%5B%22HBA%20%E9%A9%B1%E5%8A%A8%22%5D%0A%20%20HBA%20--%3E%20BUS%5B%22SAS%2FFC%2FUSB%2FiSCSI%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=s('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>SCSI 栈让「块设备」在异质总线上保持同一用户接口。代价是锁、错误恢复与历史兼容。NVMe 绕开它是性能故事；企业阵列仍大量走 SCSI 模型（包括 NVMe 之前的 FC）。不要把本课写成存储面积网拓扑课。</p><p>与调度器：请求在进入 HBA 前仍可被 mq-deadline 排序；HBA 内部还有 TCQ。</p><p>实现上：错误处理线程会阻塞该主机上的 I/O 直到复位完成，这是 SCSI 尾延迟的常见来源。iSCSI 把同一 CDB 放进 TCP，丢包会让块层看到超时而不是以太网重传细节。 读法上只引用<a href="/cs/nvme-driver">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「存储栈 / 块层到设备」课序里，对象是 <strong>SCSI 栈</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 SES 机箱管理、SCSI 保留/释放的集群锁全文。下一课在块设备之上再叠一层虚拟设备：device mapper 与 LVM。</p><p>版本字段会变，课序钉的是机制对象「SCSI 栈」，不是某一主线内核的结构体名。 后课默认：SCSI 中层把 CDB 送到 HBA。线性/条带/镜像的逻辑卷如何映射，下一课 dm/LVM。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SCSI：类驱动 + 中层 + HBA；CDB 与 sense。</li><li>与 NVMe 共享上边的块层。</li><li>device mapper 是下一课。</li><li>出处：T10 SAM；Linux SCSI；McKusick CAM；Tanenbaum <em>MOS</em>。</li></ul>',11))])}const T=r(p,[["render",C]]);export{I as __pageData,T as default};
